18	func TestInfoFlagText(t *testing.T) {
19		t.Parallel()
20		tests := []struct {
21			name     string
22			flag     string
23			want     bool
24			contains []string
25		}{
26			{"version", "--version", true, []string{"git-remote-entire 1.2.3", "Go version:", "OS/Arch:"}},
27			{"help", "--help", true, []string{"git-remote-entire 1.2.3", "entire://", "https://github.com/entireio/cli"}},
28			{"unknown flag", "--nope", false, nil},
29			{"empty", "", false, nil},
30			{"url-like arg", "entire://host/p/r", false, nil},
31		}
32		for _, tc := range tests {
33			t.Run(tc.name, func(t *testing.T) {
34				t.Parallel()
35				text, ok := infoFlagText(tc.flag, "1.2.3")
36				if ok != tc.want {
37					t.Fatalf("infoFlagText(%q) ok = %v, want %v", tc.flag, ok, tc.want)
38				}
39				if !ok {
40					if text != "" {
41						t.Fatalf("expected empty text when not handled, got %q", text)
42					}
43					return
44				}
45				for _, sub := range tc.contains {
46					if !strings.Contains(text, sub) {
47						t.Errorf("infoFlagText(%q) = %q, missing %q", tc.flag, text, sub)
48					}
49				}
50			})
51		}
52	}
53	
54	func TestParseProtocolVersion(t *testing.T) {
55		t.Parallel()
56		tests := []struct {
57			name     string
58			env      string
59			want     int
60			wantWarn string
61		}{
62			{"unset", "", 2, ""},
63			{"version_0", "version=0", 0, ""},
64			{"version_1", "version=1", 1, ""},
65			{"version_2", "version=2", 2, ""},
66			{"unknown_version_warns", "version=3", 2, "ignoring unrecognised protocol.version"},
67			{"malformed_value_warns", "version=abc", 2, "ignoring unrecognised protocol.version"},
68			{"empty_value_warns", "version=", 2, "ignoring unrecognised protocol.version"},
69			{"no_version_key", "foo=bar", 2, ""},
70			{"version_after_other_key", "foo=bar:version=1", 1, ""},
71			{"version_before_other_key", "version=2:foo=bar", 2, ""},
72		}
73		for _, tc := range tests {
74			t.Run(tc.name, func(t *testing.T) {
75				t.Parallel()
76				var buf bytes.Buffer
77				got := parseProtocolVersion(tc.env, &buf)
78				if got != tc.want {
79					t.Errorf("parseProtocolVersion(%q) = %d, want %d", tc.env, got, tc.want)
80				}
81				switch {
82				case tc.wantWarn == "" && buf.Len() != 0:
83					t.Errorf("expected no warning, got %q", buf.String())
84				case tc.wantWarn != "" && !strings.Contains(buf.String(), tc.wantWarn):
85					t.Errorf("expected warning containing %q, got %q", tc.wantWarn, buf.String())
86				}
87			})
88		}
89	}
