91	func TestGitActionFromRequest(t *testing.T) {
92		t.Parallel()
93		tests := []struct {
94			name   string
95			method string
96			path   string
97			query  string
98			want   string
99		}{
100			{"upload-pack RPC", http.MethodPost, "/et/p/r/git-upload-pack", "", "pull"},
101			{"receive-pack RPC", http.MethodPost, "/et/p/r/git-receive-pack", "", "push"},
102			{"info/refs pull", http.MethodGet, "/et/p/r/info/refs", "service=git-upload-pack", "pull"},
103			{"info/refs push", http.MethodGet, "/et/p/r/info/refs", "service=git-receive-pack", "push"},
104			{"info/refs no service", http.MethodGet, "/et/p/r/info/refs", "", ""},
105			{"unrelated GET", http.MethodGet, "/et/p/r/objects/info/packs", "", ""},
106			{"unrelated POST", http.MethodPost, "/et/p/r/whatever", "", ""},
107		}
108		for _, tc := range tests {
109			t.Run(tc.name, func(t *testing.T) {
110				t.Parallel()
111				req := httptest.NewRequestWithContext(context.Background(), tc.method, "https://host"+tc.path+"?"+tc.query, nil)
112				if got := gitActionFromRequest(req); got != tc.want {
113					t.Fatalf("gitActionFromRequest(%s %s?%s) = %q, want %q", tc.method, tc.path, tc.query, got, tc.want)
114				}
115			})
116		}
117	}
118	
119	func TestCoreTrusted(t *testing.T) {
120		t.Parallel()
121		trusted := []string{"https://core.us.entire.io", "https://core.eu.entire.io/"}
122		tests := []struct {
123			name    string
124			coreURL string
125			want    bool
126		}{
127			{"exact match", "https://core.us.entire.io", true},
128			{"trailing slash on candidate", "https://core.us.entire.io/", true},
129			{"trailing slash on trusted entry", "https://core.eu.entire.io", true},
130			{"not in set", "https://attacker.example.com", false},
131			{"empty against set", "", false},
132		}
133		for _, tc := range tests {
134			t.Run(tc.name, func(t *testing.T) {
135				t.Parallel()
136				if got := coreTrusted(tc.coreURL, trusted); got != tc.want {
137					t.Fatalf("coreTrusted(%q) = %v, want %v", tc.coreURL, got, tc.want)
138				}
139			})
140		}
141	}
142	
143	func TestCoreTrusted_EmptyTrustedSet(t *testing.T) {
144		t.Parallel()
145		if coreTrusted("https://core.us.entire.io", nil) {
146			t.Fatal("coreTrusted should be false against an empty trusted set")
147		}
148	}
149	
150	// makeTestJWT builds a three-segment JWT (alg:HS256 so ParseClaims accepts it)
151	// carrying the given aud. The signature segment is filler — the env-token path
152	// reads the aud unverified and gates it on cluster-advertised cores, never on
153	// the signature.
154	func makeTestJWT(t *testing.T, aud string) string {
155		t.Helper()
156		enc := base64.RawURLEncoding
157		header := enc.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
158		payload := enc.EncodeToString([]byte(fmt.Sprintf(`{"sub":"ci-runner","aud":%q}`, aud)))
159		return header + "." + payload + "." + enc.EncodeToString([]byte("sig"))
160	}
161	
162	// wellKnownServer serves /.well-known/entire-cluster.json advertising the given
163	// cores over TLS, returning the server and the host:port to use as clusterHost.
164	func wellKnownServer(t *testing.T, cores []string) (*httptest.Server, string) {
165		t.Helper()
166		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
167			if r.URL.Path != "/.well-known/entire-cluster.json" {
168				http.NotFound(w, r)
169				return
170			}
171			_ = json.NewEncoder(w).Encode(map[string]any{"core_urls": cores}) //nolint:errcheck // best-effort in test stub
172		}))
173		t.Cleanup(srv.Close)
174		u, err := url.Parse(srv.URL)
175		if err != nil {
176			t.Fatalf("parse server URL: %v", err)
177		}
178		return srv, u.Host
179	}
180	
181	func TestResolveEnvTokenCreds_TrustedAudSucceeds(t *testing.T) {
182		t.Parallel()
183		const core = "https://core.us.entire.io"
184		srv, clusterHost := wellKnownServer(t, []string{core})
185	
186		creds, err := resolveEnvTokenCreds(
187			t.Context(), makeTestJWT(t, core), clusterHost,
188			"https://cluster.example.com", t.TempDir(), srv.Client(),
189		)
190		if err != nil {
191			t.Fatalf("expected trusted aud to succeed, got: %v", err)
192		}
193		if creds == nil {
194			t.Fatal("expected non-nil creds for trusted aud")
195		}
196	}
197	
198	func TestResolveCreds_BlankEnvTokenFailsClosed(t *testing.T) {
199		// If ENTIRE_TOKEN is set at all, presence commits us to the env-token path:
200		// an empty or whitespace-only value must fail closed with a clear message,
201		// never silently fall back to context auth. Sets a process-global env var,
202		// so this test is not parallel.
203		dummyURL := &url.URL{Scheme: "entire", Host: "cluster.example.com"}
204		for _, blank := range []string{"", " ", "\t", "\n", " \t\n "} {
205			t.Setenv(auth.EnvTokenVar, blank)
206			creds, err := resolveCreds(t.Context(), dummyURL, "https://cluster.example.com", false, nil)
207			if err == nil {
208				t.Fatalf("blank ENTIRE_TOKEN %q should fail closed", blank)
209			}
210			if creds != nil {
211				t.Fatalf("expected nil creds for blank ENTIRE_TOKEN %q", blank)
212			}
213			if !strings.Contains(err.Error(), "blank") {
214				t.Fatalf("expected 'set but blank' error for %q, got: %v", blank, err)
215			}
216		}
217	}
218	
219	func TestResolveEnvTokenCreds_UntrustedAudAborts(t *testing.T) {
220		t.Parallel()
221		// The cluster advertises only core.us; the token's aud points elsewhere.
222		// The gate must abort before building creds (i.e. before any exchange).
223		srv, clusterHost := wellKnownServer(t, []string{"https://core.us.entire.io"})
224	
225		creds, err := resolveEnvTokenCreds(
226			t.Context(), makeTestJWT(t, "https://attacker.example.com"), clusterHost,
227			"https://cluster.example.com", t.TempDir(), srv.Client(),
228		)
229		if err == nil {
230			t.Fatal("expected untrusted aud to be rejected")
231		}
232		if creds != nil {
233			t.Fatal("expected nil creds when aud is untrusted")
234		}
235		if !strings.Contains(err.Error(), "not a trusted login server") {
236			t.Fatalf("expected trust-gate error, got: %v", err)
237		}
238	}
239	
240	func TestResolveEnvTokenCreds_EmptyAdvertisedCoresAborts(t *testing.T) {
241		t.Parallel()
242		// Discovery succeeds (HTTP 200) but advertises no cores. With nothing to
243		// trust, the gate must fail closed rather than trusting the token's aud.
244		srv, clusterHost := wellKnownServer(t, []string{})
245	
246		creds, err := resolveEnvTokenCreds(
247			t.Context(), makeTestJWT(t, "https://core.us.entire.io"), clusterHost,
248			"https://cluster.example.com", t.TempDir(), srv.Client(),
249		)
250		if err == nil {
251			t.Fatal("expected empty advertised core set to be rejected")
252		}
253		if creds != nil {
254			t.Fatal("expected nil creds when no cores are advertised")
255		}
256	}
257	
258	func TestResolveEnvTokenCreds_DiscoveryFailureAborts(t *testing.T) {
259		t.Parallel()
260		// Cluster advertises no cores (HTTP 503) → discovery fails → we must abort
261		// rather than fall back to trusting the token's own aud.
262		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
263			w.WriteHeader(http.StatusServiceUnavailable)
264		}))
265		t.Cleanup(srv.Close)
266		u, err := url.Parse(srv.URL)
267		if err != nil {
268			t.Fatalf("parse server URL: %v", err)
269		}
270	
271		creds, err := resolveEnvTokenCreds(
272			t.Context(), makeTestJWT(t, "https://core.us.entire.io"), u.Host,
273			"https://cluster.example.com", t.TempDir(), srv.Client(),
274		)
275		if err == nil {
276			t.Fatal("expected discovery failure to abort")
277		}
278		if creds != nil {
279			t.Fatal("expected nil creds on discovery failure")
280		}
281	}
282	
283	func TestResolveEnvTokenCreds_MalformedTokenAborts(t *testing.T) {
284		t.Parallel()
285		// A malformed aud must fail at the parse/validate step, before any network
286		// discovery happens — so a nil httpClient is safe here.
287		creds, err := resolveEnvTokenCreds(
288			t.Context(), makeTestJWT(t, "http://core.us.entire.io"), "cluster.example.com",
289			"https://cluster.example.com", t.TempDir(), nil,
290		)
291		if err == nil {
292			t.Fatal("expected http aud to be rejected before discovery")
293		}
294		if creds != nil {
295			t.Fatal("expected nil creds for invalid aud")
296		}
297	}
