1	//go:build authfilestore
2	
3	// File-backed auth store backend. Compiled only under the `authfilestore`
4	// build tag, which is enabled by:
5	//   - the integration test subprocess build (cmd/entire/cli/integration_test/setup_test.go)
6	//   - test:integration / test:ci tasks (mise.toml) for running this package's
7	//     tagged tests
8	//
9	// Production builds (no tag) do not include this file, so the env var below
10	// has no effect outside test environments.
11	
12	package auth
13	
14	import (
15		"encoding/json"
16		"errors"
17		"fmt"
18		"os"
19		"path/filepath"
20	)
21	
22	// testAuthStoreFileEnv, when set, redirects token storage to a JSON file at
23	// the given path instead of the OS keyring. Only honored in `authfilestore`
24	// builds.
25	const testAuthStoreFileEnv = "ENTIRE_TEST_AUTH_STORE_FILE"
26	
27	func init() {
28		chooseBackend = func() tokenBackend {
29			if path := os.Getenv(testAuthStoreFileEnv); path != "" {
30				return &fileBackend{path: path}
31			}
32			return keyringBackend{}
33		}
34	}
35	
36	type fileBackend struct {
37		path string
38	}
39	
40	func (b *fileBackend) save(service, key, value string) error {
41		tokens, err := b.read()
42		if err != nil {
43			return err
44		}
45		svc := tokens[service]
46		if svc == nil {
47			svc = make(map[string]string)
48			tokens[service] = svc
49		}
50		svc[key] = value
51		return b.write(tokens)
52	}
53	
54	func (b *fileBackend) get(service, key string) (string, error) {
55		tokens, err := b.read()
56		if err != nil {
57			return "", err
58		}
59		return tokens[service][key], nil
60	}
61	
62	func (b *fileBackend) delete(service, key string) error {
63		tokens, err := b.read()
64		if err != nil {
65			return err
66		}
67		if svc := tokens[service]; svc != nil {
68			delete(svc, key)
69			if len(svc) == 0 {
70				delete(tokens, service)
71			}
72		}
73		return b.write(tokens)
74	}
75	
76	func (b *fileBackend) read() (map[string]map[string]string, error) {
77		data, err := os.ReadFile(b.path)
78		if errors.Is(err, os.ErrNotExist) {
79			return make(map[string]map[string]string), nil
80		}
81		if err != nil {
82			return nil, fmt.Errorf("read test auth store: %w", err)
83		}
84		if len(data) == 0 {
85			return make(map[string]map[string]string), nil
86		}
87	
88		var tokens map[string]map[string]string
89		if err := json.Unmarshal(data, &tokens); err != nil {
90			return nil, fmt.Errorf("parse test auth store: %w", err)
91		}
92		if tokens == nil {
93			tokens = make(map[string]map[string]string)
94		}
95		return tokens, nil
96	}
97	
98	func (b *fileBackend) write(tokens map[string]map[string]string) error {
99		if err := os.MkdirAll(filepath.Dir(b.path), 0o700); err != nil {
100			return fmt.Errorf("create test auth store directory: %w", err)
101		}
102		data, err := json.Marshal(tokens)
103		if err != nil {
104			return fmt.Errorf("marshal test auth store: %w", err)
105		}
106		if err := os.WriteFile(b.path, data, 0o600); err != nil {
107			return fmt.Errorf("write test auth store: %w", err)
108		}
109		// os.WriteFile preserves an existing file's permission bits, so an
110		// already-broad file (e.g. 0o644 from an earlier test setup) would
111		// keep those bits. Force 0o600 to make the post-condition unconditional.
112		if err := os.Chmod(b.path, 0o600); err != nil {
113			return fmt.Errorf("restrict test auth store permissions: %w", err)
114		}
115		return nil
116	}
