	dir := t.TempDir()
	want := &contexts.File{
		CurrentContext: "eu-paul",
		Contexts: []*contexts.Context{
			{Name: "eu-paul", CoreURL: "https://eu.example", Handle: "paul", KeychainService: "entire-core:eu-paul"},
