	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if got.CurrentContext != strconv.Itoa(n) {
		t.Errorf("CurrentContext = %q, want %q (lost updates indicate non-atomic RMW)", got.CurrentContext, strconv.Itoa(n))
	}
}

